const n8=node({type:"n8n-nodes-base.code",version:2,config:{name:"Gate writer deadline and allowed origins",parameters:{"mode":"runOnceForAllItems","jsCode":"const item=$input.first();const {state,op,route}=item.json;\nif(state.stage!=='done'&&state.lockSha&&Date.now()>=state.deadline)return [{json:{...item.json,state:{...state,stage:'done',errorCategory:'writer_deadline',errorMessage:'Resume exact stored Actions run after lease expiration.'},op:null,route:'done',ledgerRequired:true}}];\nif(op){const allowed=(route==='github'&&op.url.startsWith('https://api.github.com/repos/pingpongtech-uskg/stock-web-pages/'))||(route==='notion'&&op.url.startsWith('https://api.notion.com/v1/'))||(route==='public'&&(op.url==='https://openapi.twse.com.tw/v1/holidaySchedule/holidaySchedule'||op.url.startsWith(state.siteUrl+'/data/screening-export.json?')||(state.archiveMethod==='legacy_archive'&&op.url.startsWith(state.siteUrl+state.archivePath+'?'))))||(route==='zip'&&/^https:\\/\\/[a-zA-Z0-9.-]+\\.(blob\\.core\\.windows\\.net|actions\\.githubusercontent\\.com|githubusercontent\\.com)\\//.test(op.url));if(!allowed)throw Error('request_origin_rejected');}\nreturn [item];"},position:[780,360]}});
