const n11=node({type:"n8n-nodes-base.code",version:2,config:{name:"Recover native dispatch response without redispatch",parameters:{"mode":"runOnceForAllItems","jsCode":"// Sanitized observations survive execution retention; recovery authority remains GitHub CAS.\nfunction safeOutcomeText(value) {return String(value||'').replace(/https?:\\/\\/\\S+/g,'[URL redacted]').slice(0,1000);}\nfunction operationOutcome(state) {\n  const screeningStatus=state.screeningStatus||'pending',notionStatus=state.notionStatus||'pending',deployStatus=state.deployStatus||'pending';\n  const outcome=screeningStatus==='diagnostic_verified'?'diagnostics_only':screeningStatus==='skipped_non_trading'?'skipped_non_trading':screeningStatus==='already_complete'?'already_complete':screeningStatus==='complete'&&notionStatus==='complete'?(deployStatus==='verified'?'complete':'deployment_pending'):state.errorCategory?'failed':'in_progress';\n  const actionsRunId=/^\\d{1,24}$/.test(state.actionsRunId||'')?state.actionsRunId:'';\n  const pageId=/^[a-f0-9-]{36}$/.test(state.notionPageId||'')?state.notionPageId:'';\n  return {outcome,marketDate:state.marketDate,requestedAtDate:state.requestedAtDate||state.marketDate,requestId:state.requestId,stage:state.stage,owner:state.owner,screeningStatus,notionStatus,deployStatus,publicationStatus:state.publicationStatus||'pending',actionsRunId,runId:state.runId||'',revision:state.revision||'',payloadHash:state.payloadHash||'',expectedCount:state.expectedCount??null,archivedCount:state.archivedCount??null,actionsUrl:actionsRunId?'https://github.com/pingpongtech-uskg/stock-web-pages/actions/runs/'+actionsRunId:null,notionUrl:pageId?'https://www.notion.so/'+pageId.replaceAll('-',''):null,publishedGitCommit:/^[a-f0-9]{40}$/.test(state.publication?.publishedGitCommit||'')?state.publication.publishedGitCommit:null,errorCategory:state.errorCategory||'',errorMessage:safeOutcomeText(state.errorMessage),diagnosticsOnly:screeningStatus==='diagnostic_verified',deadline:state.deadline||null,scheduledCutoff:state.scheduledCutoff||state.overdueAt||null,manualDeadlineOverride:state.manualDeadlineOverride||false};\n}\nfunction nativeDispatchResponse(value) {\n  const error=value?.error;\n  const code=Number(value?.statusCode||error?.statusCode||error?.httpCode||error?.cause?.statusCode||0);\n  const statusCode=code>=100&&code<600?code:error?503:204;\n  return {statusCode,body:error?{message:safeOutcomeText(error.message||error)}:{},headers:value?.headers||error?.headers||error?.response?.headers||{},...(error&&statusCode>=500?{error:true}:{})};\n}\n\nreturn [{json:{state:$('Choose visible business stage').item.json.state,response:nativeDispatchResponse($input.first().json)}}];"},position:[520,540]}});
